def validate_configuration():
    errors = []
    if BATCH_SIZE < 1:
        errors.append(f"BATCH_SIZE={BATCH_SIZE}; must be >= 1.")
    if EPOCHS < 1:
        errors.append(f"EPOCHS={EPOCHS}; must be >= 1.")
    if MAX_FRAMES < 2:
        errors.append(f"MAX_FRAMES={MAX_FRAMES}; must be >= 2.")
    if MAX_TOKENS < 3:
        errors.append(f"MAX_TOKENS={MAX_TOKENS}; must be >= 3.")
    if MODEL_DIM % ATTENTION_HEADS != 0:
        errors.append(f"MODEL_DIM={MODEL_DIM} not divisible by ATTENTION_HEADS={ATTENTION_HEADS}.")
    if MAX_SAMPLES_PER_SPLIT < 0:
        errors.append(f"MAX_SAMPLES_PER_SPLIT={MAX_SAMPLES_PER_SPLIT}; must be >= 0 (0 = no limit).")
    if TRAIN_RECOGNITION:
        if ISOLATED_MANIFEST is None:
            errors.append("TRAIN_RECOGNITION=True but ISOLATED_MANIFEST is None.")
        elif not Path(ISOLATED_MANIFEST).is_file():
            errors.append(f"ISOLATED_MANIFEST does not exist: {ISOLATED_MANIFEST}")
        if ISOLATED_LICENSE.strip().lower() in ("", "unverified", "unknown", "none"):
            errors.append("TRAIN_RECOGNITION=True but ISOLATED_LICENSE is unresolved; set a verified license or disable training.")
    if TRAIN_TRANSLATION:
        if TRANSLATION_MANIFEST is None:
            errors.append("TRAIN_TRANSLATION=True but TRANSLATION_MANIFEST is None.")
        elif not Path(TRANSLATION_MANIFEST).is_file():
            errors.append(f"TRANSLATION_MANIFEST does not exist: {TRANSLATION_MANIFEST}")
        if TRANSLATION_LICENSE.strip().lower() in ("", "unverified", "unknown", "none"):
            errors.append("TRAIN_TRANSLATION=True but TRANSLATION_LICENSE is unresolved; set a verified license or disable training.")
        if "nc" in TRANSLATION_LICENSE.lower() and not ALLOW_RESEARCH_ONLY_DATASETS:
            errors.append("Translation dataset appears research-only; set ALLOW_RESEARCH_ONLY_DATASETS=True after confirming terms for your use.")
    if (TRAIN_RECOGNITION or TRAIN_TRANSLATION) and not CONFIRM_DATASET_RIGHTS:
        errors.append("CONFIRM_DATASET_RIGHTS=False; set True only after verifying dataset rights.")
    if errors:
        raise ValueError("Configuration validation failed:\n" + "\n".join(f"  - {e}" for e in errors))
    print("Configuration validation passed.")

validate_configuration()

TOTAL_LANDMARKS = 543
RAW_FEATURE_DIM = 1629
COMPONENT_ORDER = ["POSE_LANDMARKS", "FACE_LANDMARKS", "LEFT_HAND_LANDMARKS", "RIGHT_HAND_LANDMARKS"]
COMPONENT_RANGES = {
    "POSE_LANDMARKS": [0, 33], "FACE_LANDMARKS": [33, 501],
    "LEFT_HAND_LANDMARKS": [501, 522], "RIGHT_HAND_LANDMARKS": [522, 543],
}


class IsolatedWordNet(nn.Module):
    def __init__(self, class_count):
        super().__init__()
        self.layers = nn.Sequential(
            nn.Conv1d(225, 64, kernel_size=5, padding=2), nn.GELU(),
            nn.Conv1d(64, 96, kernel_size=3, padding=1), nn.GELU(),
            nn.AdaptiveAvgPool1d(1), nn.Flatten(),
            nn.Linear(96, class_count),
        )
    def forward(self, features):
        return self.layers(features.transpose(1, 2))


class FrameProjection(nn.Module):
    def __init__(self, input_dim, d_model):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(input_dim, 384), nn.LayerNorm(384), nn.GELU(), nn.Dropout(0.10),
            nn.Linear(384, d_model), nn.LayerNorm(d_model),
        )
        self.temporal = nn.Conv1d(d_model, d_model, kernel_size=5, padding=2, groups=d_model)
    def forward(self, x):
        delta = torch.zeros_like(x)
        delta[:, 1:] = x[:, 1:] - x[:, :-1]
        return self.temporal(self.net(torch.cat([x, delta], dim=-1)).transpose(1, 2)).transpose(1, 2)


class PositionalEncoding(nn.Module):
    def __init__(self, d_model, max_len):
        super().__init__()
        pos = torch.arange(max_len, dtype=torch.float32).unsqueeze(1)
        div = torch.exp(torch.arange(0, d_model, 2, dtype=torch.float32) * (-math.log(10000.0) / d_model))
        pe = torch.zeros(max_len, d_model)
        pe[:, 0::2] = torch.sin(pos * div)
        pe[:, 1::2] = torch.cos(pos * div)
        self.register_buffer("pe", pe.unsqueeze(0))
    def forward(self, x):
        return x + self.pe[:, :x.size(1)]


class SignTransformer(nn.Module):
    def __init__(self, input_dim, vocab_size, max_frames, max_tokens, pad_idx,
                 d_model=128, nhead=4, layers=2, ff=512, dropout=0.15, norm_first=False):
        super().__init__()
        self.pad_idx = pad_idx
        self.input_proj = FrameProjection(input_dim, d_model)
        self.src_pos = PositionalEncoding(d_model, max_frames + 4)
        self.tok_embed = nn.Embedding(vocab_size, d_model, padding_idx=pad_idx)
        self.tgt_pos = PositionalEncoding(d_model, max_tokens + 4)
        enc = nn.TransformerEncoderLayer(d_model, nhead, ff, dropout, batch_first=True, norm_first=norm_first)
        dec = nn.TransformerDecoderLayer(d_model, nhead, ff, dropout, batch_first=True, norm_first=norm_first)
        self.encoder = nn.TransformerEncoder(enc, layers)
        self.decoder = nn.TransformerDecoder(dec, layers)
        self.out = nn.Linear(d_model, vocab_size)
        self.scale = d_model ** 0.5
    def encode(self, frames, src_pad):
        return self.encoder(self.src_pos(self.input_proj(frames)), src_key_padding_mask=src_pad)
    def decode(self, tokens, memory, tgt_mask, src_pad, tgt_pad=None):
        x = self.tgt_pos(self.tok_embed(tokens) * self.scale)
        return self.out(self.decoder(x, memory, tgt_mask=tgt_mask,
                    tgt_key_padding_mask=tgt_pad, memory_key_padding_mask=src_pad))
    def forward(self, frames, src_pad, tokens, tgt_mask):
        return self.decode(tokens, self.encode(frames, src_pad), tgt_mask, src_pad,
                           tgt_pad=tokens.eq(self.pad_idx))


def source_padding_mask(lengths, max_len):
    return torch.arange(max_len, device=lengths.device).unsqueeze(0) >= lengths.unsqueeze(1)


def causal_mask(size, device):
    return torch.triu(torch.ones(size, size, dtype=torch.bool, device=device), diagonal=1)


def synthetic_smoke_check():
    torch.manual_seed(SEED)
    recognition = IsolatedWordNet(3).to(DEVICE)
    x = torch.randn(2, 64, 225, device=DEVICE)
    y = torch.tensor([0, 2], device=DEVICE)
    loss_a = nn.functional.cross_entropy(recognition(x), y)
    loss_a.backward()
    assert torch.isfinite(loss_a), "Recognition smoke loss is not finite"
    translation = SignTransformer(input_dim=32, vocab_size=12, max_frames=8, max_tokens=6,
                                  pad_idx=0, d_model=32, nhead=4, layers=1, ff=64).to(DEVICE)
    poses = torch.randn(2, 8, 16, device=DEVICE)
    lengths = torch.tensor([8, 5], device=DEVICE)
    src_mask = source_padding_mask(lengths, poses.size(1))
    tokens = torch.tensor([[2, 4, 5], [2, 6, 0]], device=DEVICE)
    logits = translation(poses, src_mask, tokens, causal_mask(tokens.size(1), DEVICE))
    target = torch.tensor([[4, 5, 3], [6, 3, -100]], device=DEVICE)
    loss_b = nn.functional.cross_entropy(logits.reshape(-1, 12), target.reshape(-1), ignore_index=-100)
    loss_b.backward()
    assert logits.shape == (2, 3, 12), f"Unexpected translation logits shape: {logits.shape}"
    assert torch.isfinite(loss_b), "Translation smoke loss is not finite"
    print(f"Synthetic smoke passed: recognition_loss={loss_a.item():.4f}, translation_loss={loss_b.item():.4f}")


if RUN_SYNTHETIC_SMOKE:
    synthetic_smoke_check()

def read_csv_rows(path):
    path = Path(path)
    if not path.is_file():
        raise FileNotFoundError(f"CSV not found: {path}")
    with path.open(newline="", encoding="utf-8-sig") as stream:
        reader = csv.DictReader(stream)
        rows = list(reader)
        fields = reader.fieldnames or []
    if not rows:
        raise ValueError(f"No data rows in {path}")
    print(f"{path}: {len(rows):,} rows; fields={fields}")
    return rows, fields


def validate_landmarks(sequence, source):
    arr = np.asarray(sequence)
    if arr.ndim != 3 or arr.shape[1:] != (TOTAL_LANDMARKS, 3):
        raise ValueError(f"{source}: expected (T,543,3), received {arr.shape}")
    if len(arr) < 2:
        raise ValueError(f"{source}: need at least two frames")
    if arr.dtype.kind not in "iuf" or not np.isfinite(arr).all():
        raise ValueError(f"{source}: landmarks must be numeric and finite")
    return arr.astype(np.float32, copy=False)


def normalize_pose_sequence(flat):
    arr = np.asarray(flat)
    if arr.ndim != 2 or arr.shape[1] != RAW_FEATURE_DIM or arr.dtype.kind not in "iuf":
        raise ValueError(f"Expected numeric (T,{RAW_FEATURE_DIM}), received {arr.shape}/{arr.dtype}")
    x = arr.reshape(len(arr), TOTAL_LANDMARKS, 3).astype(np.float32)
    with np.errstate(invalid="ignore"):
        center = np.nanmean(x[:, [23, 24], :], axis=1, keepdims=True)
    bad = ~np.isfinite(center).all(axis=(1, 2))
    if bad.any():
        with np.errstate(invalid="ignore"):
            center[bad] = np.nanmean(x[bad, :33, :], axis=1, keepdims=True)
    x -= center
    with np.errstate(invalid="ignore"):
        scales = np.nanstd(x[:, :33, :].reshape(len(x), -1), axis=1)
    valid = scales[np.isfinite(scales) & (scales > 1e-6)]
    scale = float(np.nanmedian(valid)) if len(valid) else 1.0
    if not math.isfinite(scale) or scale <= 1e-6:
        scale = 1.0
    return np.nan_to_num(x / scale, nan=0.0, posinf=0.0, neginf=0.0).reshape(len(x), -1).astype(np.float32)


def resize_sequence(sequence, target_len):
    seq = np.asarray(sequence)
    if seq.ndim != 2 or not len(seq):
        raise ValueError(f"Expected non-empty (T,D), got {seq.shape}")
    if len(seq) > target_len:
        idx = np.linspace(0, len(seq) - 1, target_len).round().astype(np.int64)
        return seq[idx].astype(np.float32), target_len
    out = np.zeros((target_len, seq.shape[1]), dtype=np.float32)
    out[:len(seq)] = seq
    return out, len(seq)


def resolve_input_path(value, root):
    candidate = Path(str(value))
    return candidate if candidate.is_absolute() else Path(root) / candidate


def atomic_torch_save(payload, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    torch.save(payload, temporary)
    os.replace(temporary, path)


def atomic_json_save(payload, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")
    os.replace(temporary, path)


def fingerprint_rows(rows, fields):
    payload = [[str(row.get(field, "")) for field in fields] for row in rows]
    return hashlib.sha256(json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode()).hexdigest()

MIN_SPLIT_SIZE = 2  # after limiting; raise if a non-empty split would fall below this


def split_grouped(records, group_key, seed=SEED):
    groups = defaultdict(list)
    for row in records:
        group = str(row.get(group_key, "")).strip()
        if not group:
            raise ValueError(f"Missing group value for {group_key}; refusing leaky split.")
        groups[group].append(row)
    if len(groups) < 3:
        raise ValueError(f"Need at least three independent {group_key} groups; found {len(groups)}")
    keys = list(groups)
    random.Random(seed).shuffle(keys)
    targets = {"train": 0.8, "validation": 0.1, "test": 0.1}
    result = {name: [] for name in targets}
    total = sum(len(rows) for rows in groups.values())
    for group in keys:
        name = min(targets, key=lambda key: len(result[key]) / max(targets[key] * total, 1))
        result[name].extend(groups[group])
    all_groups = {name: {r[group_key] for r in rows} for name, rows in result.items()}
    if (all_groups["train"] & all_groups["validation"] or
        all_groups["train"] & all_groups["test"] or
        all_groups["validation"] & all_groups["test"]):
        raise AssertionError(f"Group leakage in {group_key} split")
    return result


def limit_split(rows, limit, seed, split_name="split"):
    if not limit or len(rows) <= limit:
        return rows
    sampled = random.Random(seed).sample(rows, limit)
    if len(sampled) < MIN_SPLIT_SIZE:
        raise ValueError(
            f"Limiting {split_name} to {limit} produced {len(sampled)} samples, "
            f"below MIN_SPLIT_SIZE={MIN_SPLIT_SIZE}. Increase MAX_SAMPLES_PER_SPLIT or use full mode."
        )
    return sampled

def _read_pose_format(path):
    try:
        from pose_format import Pose
    except ImportError as exc:
        raise ImportError("Reading .pose requires `pip install pose-format`.") from exc
    pose = Pose.read(Path(path).read_bytes())
    names = [component.name for component in pose.header.components]
    points = sum(len(component.points) for component in pose.header.components)
    if names[:len(COMPONENT_ORDER)] != COMPONENT_ORDER or points < TOTAL_LANDMARKS:
        raise ValueError(f"{path}: incompatible pose header; components={names}, points={points}")
    data = np.asarray(np.ma.filled(pose.body.data, 0.0), dtype=np.float32)
    if data.ndim != 4 or data.shape[1] < 1 or data.shape[2] < TOTAL_LANDMARKS or data.shape[3] < 3:
        raise ValueError(f"{path}: unexpected pose tensor shape {data.shape}")
    return validate_landmarks(data[:, 0, :TOTAL_LANDMARKS, :3], path)


def _video_landmarks(path):
    try:
        import cv2
        import mediapipe as mp
    except ImportError as exc:
        raise ImportError("Video extraction requires `pip install mediapipe opencv-python-headless`.") from exc
    cap = cv2.VideoCapture(str(path))
    if not cap.isOpened():
        raise ValueError(f"Cannot open video: {path}")
    sequences = []
    def points_or_zeros(component, count):
        if component is None:
            return np.zeros((count, 3), dtype=np.float32)
        points = np.asarray([[p.x, p.y, p.z] for p in component.landmark], dtype=np.float32)
        if points.shape != (count, 3):
            raise ValueError(f"Unexpected MediaPipe component shape {points.shape}; expected {(count, 3)}")
        return points
    with mp.solutions.holistic.Holistic(
        static_image_mode=False, model_complexity=1,
        enable_segmentation=False, refine_face_landmarks=False,
    ) as holistic:
        try:
            while True:
                ok, frame = cap.read()
                if not ok:
                    break
                result = holistic.process(cv2.cvtColor(frame, cv2.COLOR_BGR2RGB))
                sequences.append(np.concatenate([
                    points_or_zeros(result.pose_landmarks, 33),
                    points_or_zeros(result.face_landmarks, 468),
                    points_or_zeros(result.left_hand_landmarks, 21),
                    points_or_zeros(result.right_hand_landmarks, 21),
                ], axis=0))
        finally:
            cap.release()
    return validate_landmarks(np.asarray(sequences), path)


def load_landmarks(path, cache_dir=None):
    path = Path(path)
    if not path.is_file():
        raise FileNotFoundError(f"Sample file not found: {path}")
    suffix = path.suffix.lower()
    if suffix == ".pose":
        return _read_pose_format(path)
    if suffix in (".mp4", ".mov", ".avi", ".mkv"):
        if cache_dir is None:
            return _video_landmarks(path)
        cache_dir = Path(cache_dir)
        cache_dir.mkdir(parents=True, exist_ok=True)
        stat = path.stat()
        key = hashlib.sha256(f"{path.resolve()}:{stat.st_size}:{stat.st_mtime_ns}".encode()).hexdigest()
        cached = cache_dir / f"{key}.npy"
        if not cached.exists():
            np.save(cached, _video_landmarks(path))
        return validate_landmarks(np.load(cached, allow_pickle=False), path)
    if suffix == ".npy":
        return validate_landmarks(np.load(path, allow_pickle=False), path)
    if suffix == ".npz":
        with np.load(path, allow_pickle=False) as archive:
            candidates = [k for k in ("landmarks", "pose", "poses") if k in archive]
            if not candidates:
                raise ValueError(f"{path}: .npz must contain landmarks, pose, or poses")
            return validate_landmarks(archive[candidates[0]], path)
    raise ValueError(f"Unsupported sample format {suffix!r}: {path}")


def prepare_isolated_features(landmarks):
    arr = validate_landmarks(landmarks, "recognition sample")
    selected = arr[:, list(range(33)) + list(range(501, 543)), :]
    hips = (selected[:, 23] + selected[:, 24]) * 0.5
    shoulder = np.linalg.norm(selected[:, 11, :2] - selected[:, 12, :2], axis=1)
    valid = shoulder[shoulder > 1e-5]
    scale = float(np.median(valid)) if len(valid) else 1.0
    selected = (selected - hips[:, None, :]) / scale
    indices = np.linspace(0, len(selected) - 1, 64).round().astype(int)
    features = selected[indices].reshape(64, 225).astype(np.float32)
    if not np.isfinite(features).all():
        raise ValueError("Non-finite recognition features")
    return features


def load_isolated_records():
    if ISOLATED_MANIFEST is None:
        raise ValueError("Set ISOLATED_MANIFEST before enabling recognition.")
    rows, fields = read_csv_rows(ISOLATED_MANIFEST)
    required = {ISOLATED_PATH_COLUMN, ISOLATED_LABEL_COLUMN}
    if not required.issubset(fields):
        raise ValueError(f"Recognition manifest missing {sorted(required - set(fields))}; found {fields}")
    records, errors = [], []
    for index, row in enumerate(rows):
        label = str(row.get(ISOLATED_LABEL_COLUMN, "")).strip()
        path = resolve_input_path(row.get(ISOLATED_PATH_COLUMN, ""), ISOLATED_DATA_ROOT)
        try:
            if not label:
                raise ValueError("empty sign label")
            features = prepare_isolated_features(load_landmarks(path, OUTPUT_ROOT / "cache" / "video_poses"))
            video = str(row.get(ISOLATED_VIDEO_COLUMN, "")).strip() or path.stem
            signer = str(row.get(ISOLATED_SIGNER_COLUMN, "")).strip() if ISOLATED_SIGNER_COLUMN else ""
            records.append({"features": features, "label": label, "video_id": video,
                            "signer": signer, "path": str(path)})
        except Exception as exc:
            errors.append(f"row {index + 2} ({path}): {exc}")
    if errors:
        print(f"Invalid recognition samples: {len(errors)}")
        print("\n".join(errors[:20]))
        raise ValueError("Recognition data validation failed; invalid samples were not silently discarded.")
    if len(records) < 3:
        raise ValueError(f"Need at least three valid recognition samples, found {len(records)}")
    labels = sorted({row["label"] for row in records})
    if len(labels) < 2:
        raise ValueError(f"Need at least two isolated-sign classes, found {labels}")
    print(f"recognition rows={len(records)}; classes={len(labels)}")
    return records

def _resolve_glosl_pose(value, root):
    root = Path(root)
    val_str = str(value).replace("\\", "/")
    direct = root / val_str
    if direct.is_file():
        return direct
    under_poses = root / "poses" / val_str
    if under_poses.is_file():
        return under_poses
    if val_str.startswith("poses/"):
        stripped = root / val_str[6:]
        if stripped.is_file():
            return stripped
    stem = Path(val_str).stem
    matches = list(root.rglob(f"{stem}.pose"))
    if len(matches) == 1:
        return matches[0]
    subdirs = [p.name for p in root.iterdir() if p.is_dir()] if root.exists() else []
    raise FileNotFoundError(
        f"GloSL pose not found: {value}\nAttempted: {direct}, {under_poses}; stem matches={len(matches)}\n"
        f"TRANSLATION_POSE_ROOT={root.resolve()} (subdirs: {subdirs})"
    )


def _isign_source_video(uid):
    """iSign UIDs look like '[video_id]-[sequence_number]'."""
    text = str(uid).strip()
    if "-" not in text:
        raise ValueError(f"iSign UID {uid!r} does not match [video_id]-[sequence_number]")
    return text.rsplit("-", 1)[0]


def _pose_path_index(root):
    root = Path(root)
    if not root.is_dir():
        raise FileNotFoundError(f"Pose root not found: {root}")
    index = {}
    for path in root.rglob("*"):
        if path.is_file() and path.suffix.lower() in (".pose", ".npy", ".npz"):
            index.setdefault(path.stem, path)
    return index


def load_translation_records():
    if TRANSLATION_MANIFEST is None:
        raise ValueError("Set TRANSLATION_MANIFEST before enabling translation.")
    rows, fields = read_csv_rows(TRANSLATION_MANIFEST)
    root = Path(TRANSLATION_POSE_ROOT)
    fmt = TRANSLATION_FORMAT
    if fmt == "auto":
        if {"pose_file", "text"}.issubset(fields):
            fmt = "glosl"
        elif {"uid", "text"}.issubset(fields):
            fmt = "isign"
        elif {"pose_path", "text"}.issubset(fields):
            fmt = "canonical"
        else:
            raise ValueError(f"Cannot infer format from fields {fields}; set TRANSLATION_FORMAT.")
    pose_index = None
    records = []
    for number, row in enumerate(rows, start=2):
        text = str(row.get("text", "")).strip()
        if not text:
            raise ValueError(f"Row {number}: empty English target.")
        if fmt == "glosl":
            path = _resolve_glosl_pose(row.get("pose_file", ""), root)
            video = str(row.get("video_ref", "")).strip() or path.stem
            split_name = str(row.get("split", "")).strip().lower()
            signer = str(row.get("signer", "")).strip()
            uid = str(row.get("id", number))
        elif fmt == "isign":
            uid_raw = str(row.get("uid", "")).strip()
            if not uid_raw:
                raise ValueError(f"Row {number}: empty uid.")
            if pose_index is None:
                pose_index = _pose_path_index(root)
            path = pose_index.get(uid_raw)
            if path is None:
                raise FileNotFoundError(f"No pose file matches iSign uid {uid_raw!r}.")
            video = _isign_source_video(uid_raw)
            signer = str(row.get("signer", "")).strip()
            split_name = str(row.get("split", "")).strip().lower()
            uid = uid_raw
        elif fmt == "canonical":
            path = resolve_input_path(row.get("pose_path", ""), root)
            video = str(row.get("video_id", "")).strip()
            split_name = str(row.get("split", "")).strip().lower()
            signer = str(row.get("signer", "")).strip()
            uid = str(row.get("uid") or row.get("id") or number)
        else:
            raise ValueError(f"Unsupported TRANSLATION_FORMAT={fmt!r}")
        if not video:
            raise ValueError(f"Row {number}: missing source video identity.")
        if not path.is_file():
            raise FileNotFoundError(f"Row {number}: pose file missing: {path}")
        split_name = {"dev": "validation", "val": "validation"}.get(split_name, split_name)
        records.append({"path": path, "text": text, "video_id": video, "signer": signer,
                        "official_split": split_name, "uid": uid})
    print(f"translation format={fmt}; aligned rows={len(records):,}")
    return records, fmt


def assign_translation_splits(records):
    signer_complete = all(row["signer"] for row in records)
    if signer_complete:
        split = split_grouped(records, "signer")
        policy = "signer-independent"
    elif all(row["official_split"] in ("train", "validation", "test") for row in records):
        split = {name: [r for r in records if r["official_split"] == name]
                 for name in ("train", "validation", "test")}
        policy = "published source-video split; signer independence unavailable"
    else:
        split = split_grouped(records, "video_id")
        policy = "source-video-independent; signer independence unavailable"
    video_sets = {name: {r["video_id"] for r in rows} for name, rows in split.items()}
    pairs = [("train", "validation"), ("train", "test"), ("validation", "test")]
    for left, right in pairs:
        overlap = video_sets[left] & video_sets[right]
        if overlap:
            raise ValueError(f"Video leakage between {left} and {right}: {len(overlap)} shared videos.")
    if signer_complete:
        signer_sets = {name: {r["signer"] for r in rows} for name, rows in split.items()}
        for left, right in pairs:
            if signer_sets[left] & signer_sets[right]:
                raise ValueError(f"Signer leakage between {left} and {right}.")
    print(f"split policy={policy}; " + "; ".join(f"{k}={len(v)}" for k, v in split.items()))
    return split, signer_complete, policy


def load_translation_split(split_rows):
    loaded, errors = [], []
    for row in split_rows:
        try:
            landmarks = load_landmarks(row["path"])
            norm = normalize_pose_sequence(landmarks.reshape(len(landmarks), RAW_FEATURE_DIM))
            frames, length = resize_sequence(norm, MAX_FRAMES)
            loaded.append({**row, "frames": frames, "length": length})
        except Exception as exc:
            errors.append(f"{row['uid']} ({row['path']}): {exc}")
    if errors:
        print(f"Invalid aligned samples: {len(errors)}")
        print("\n".join(errors[:20]))
        raise ValueError("Translation validation failed; invalid samples were not discarded.")
    if not loaded:
        raise ValueError("No valid pose-to-English pairs in split.")
    return loaded


def prepare_translation_data():
    if not CONFIRM_DATASET_RIGHTS:
        raise PermissionError("Set CONFIRM_DATASET_RIGHTS=True before training.")
    records, fmt = load_translation_records()
    dataset_name, dataset_license = TRANSLATION_DATASET_NAME, TRANSLATION_LICENSE
    if fmt == "glosl":
        dataset_name, dataset_license = "GloSL-ISL", "CC BY-NC 4.0"
    elif fmt == "isign":
        dataset_name, dataset_license = "iSign", "CC BY-NC-SA 4.0"
    if "nc" in dataset_license.lower() and not ALLOW_RESEARCH_ONLY_DATASETS:
        raise PermissionError(f"{dataset_name} is research-only. Set ALLOW_RESEARCH_ONLY_DATASETS=True only for research.")
    splits, signer_complete, policy = assign_translation_splits(records)
    splits = {name: limit_split(rows, MAX_SAMPLES_PER_SPLIT, SEED + i, name)
              for i, (name, rows) in enumerate(splits.items())}
    loaded = {name: load_translation_split(rows) for name, rows in splits.items()}
    unique_targets = len({row["text"] for name in loaded for row in loaded[name]})
    print("=" * 70)
    print("MODEL B PREFLIGHT")
    print("=" * 70)
    print(f"valid pairs={len(records)}; unique English targets={unique_targets}")
    print(f"split sizes: {', '.join(f'{k}={len(v)}' for k, v in loaded.items())}")
    print(f"source format={fmt}; split policy={policy}; signer_complete={signer_complete}")
    print(f"feature shape={loaded['train'][0]['frames'].shape}; model input dim={RAW_FEATURE_DIM * 2}")
    print(f"license={dataset_license}; scope={TRAINING_SCOPE}")
    return loaded, signer_complete, policy, fmt, len(records), dataset_name, dataset_license

